def transform(grid):
    out=[row[:] for row in grid]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 3:
                out[r][c]=4
                if grid[r][0] == 9:
                    for x in range(1,c): out[r][x]=3
                elif grid[r][-1] == 9:
                    for x in range(c+1,len(grid[0])-1): out[r][x]=3
    return out
